. (Join-Path $PSScriptRoot '..\lib\environment.ps1')
. (Join-Path $PSScriptRoot '..\lib\processes.ps1')
$mode=if(Test-Path (Join-Path $script:V4Root 'runtime\active-mode')){(Get-Content (Join-Path $script:V4Root 'runtime\active-mode') -Raw).Trim()}else{'none'};Write-Portal "Mode: $mode"
$compose=docker compose -f $script:ComposeFile ps --format json|ConvertFrom-Json
foreach($service in 'database','phpmyadmin','database-preview','deployment-preview'){ $row=$compose|Where-Object service -eq $service;if($row){Write-Portal "$service container: $($row.State)"} }
if($mode -eq 'deployment-preview'){try{$h=Invoke-WebRequest http://127.0.0.1:8184/ -UseBasicParsing -TimeoutSec 3;Write-Portal "Apache/frontend: healthy ($($h.StatusCode)) http://127.0.0.1:8184"}catch{Write-Portal 'Apache/frontend: unhealthy'};try{$a=Invoke-WebRequest http://127.0.0.1:8184/api/v1/health -UseBasicParsing -TimeoutSec 3;Write-Portal "API health: healthy ($($a.StatusCode))"}catch{Write-Portal 'API health: unhealthy'};Write-Portal 'Database: dnd_portal_v4_preview';Write-Portal 'phpMyAdmin: http://127.0.0.1:8096';Write-Portal "ZIP SHA256: $((Get-FileHash (Join-Path $script:V4Root 'release\dnd-portal-v4-htdocs.zip')).Hash)"}
elseif($mode -eq 'development'){foreach($name in 'backend-development','frontend-development'){$f=Join-Path $script:V4Root "runtime\$name.pid";if(Test-Path $f){$id=[int](Get-Content $f);$running=Get-Process -Id $id -ErrorAction SilentlyContinue;if($running){Write-Portal "${name}: running PID $id"}else{Write-Portal "${name}: stopped (stale PID $id)"}}else{Write-Portal "${name}: stopped"}};$backendHealthy=$false;$frontendHealthy=$false;try{$a=Invoke-WebRequest http://127.0.0.1:8110/api/v1/health -UseBasicParsing -TimeoutSec 3;$backendHealthy=$a.StatusCode -eq 200;Write-Portal "Backend health: $(if($backendHealthy){'healthy'}else{'unhealthy'}) ($($a.StatusCode)) http://127.0.0.1:8110"}catch{Write-Portal 'Backend health: unhealthy'};try{$f=Invoke-WebRequest http://127.0.0.1:5174/ -UseBasicParsing -TimeoutSec 3;$frontendHealthy=$f.StatusCode -eq 200;Write-Portal "Frontend health: $(if($frontendHealthy){'healthy'}else{'unhealthy'}) ($($f.StatusCode)) http://127.0.0.1:5174"}catch{Write-Portal 'Frontend health: unhealthy'};if(!$frontendHealthy){try{$alt=Invoke-WebRequest http://127.0.0.1:5175/ -UseBasicParsing -TimeoutSec 3;Write-Portal "Frontend port deviation: canonical 5174 is unhealthy, but 5175 responds ($($alt.StatusCode)); this is not a valid V4 frontend."}catch{}};$pmaHealthy=$false;try{$pmaEnv=Join-Path $script:V4Root 'runtime\phpmyadmin.env';$values=@{};foreach($line in Get-Content $pmaEnv){$key,$value=$line.Split('=',2);$values[$key]=$value};$pmaSession=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$loginPage=Invoke-WebRequest http://127.0.0.1:8096/ -WebSession $pmaSession -UseBasicParsing -TimeoutSec 3;$token=[regex]::Match($loginPage.Content,'name="token" value="([^"]+)"').Groups[1].Value;if($token){$form=@{pma_username=$values.PMA_USER;pma_password=$values.PMA_PASSWORD;server='1';token=$token};$loggedIn=Invoke-WebRequest http://127.0.0.1:8096/index.php -Method Post -WebSession $pmaSession -Body $form -UseBasicParsing -TimeoutSec 5;$pmaHealthy=$loggedIn.Content -match 'dnd_portal_v4_development' -and $loggedIn.Content -notmatch 'Cannot connect|Access denied'};Write-Portal "phpMyAdmin health: $(if($pmaHealthy){'healthy'}else{'unhealthy'}) (authenticated database check) http://127.0.0.1:8096"}catch{Write-Portal 'phpMyAdmin health: unhealthy (database authentication failed)'};Write-Portal "Database health: $(if($backendHealthy){'healthy'}else{'unhealthy'}) via backend PDO";Write-Portal 'Database: dnd_portal_v4_development / 127.0.0.1:3310'}
